package com.bank.numbers;

import org.springframework.stereotype.Service;
import java.util.*;

@Service
public class SecondLargestService {

    public Optional<Integer> findSecondLargest(List<Integer> numbers) {
        return numbers.stream()
            .distinct()                              // remove duplicate values
            .sorted(Comparator.reverseOrder())       // descending
            .skip(1)                                 // skip the largest
            .findFirst();                            // second-largest
    }
}
