package com.bank.numbers;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class SecondLargestTest {

    @Test void basic() {
        assertThat(List.of(10, 20, 30, 40, 50).stream()
            .distinct().sorted(Comparator.reverseOrder()).skip(1).findFirst())
            .contains(40);
    }

    @Test void withDuplicateMax() {
        assertThat(List.of(50, 50, 30, 40).stream()
            .distinct().sorted(Comparator.reverseOrder()).skip(1).findFirst())
            .contains(40);  // NOT another 50!
    }

    @Test void singleElement() {
        assertThat(List.of(10).stream()
            .distinct().sorted(Comparator.reverseOrder()).skip(1).findFirst())
            .isEmpty();
    }

    @Test void allSame() {
        assertThat(List.of(5, 5, 5).stream()
            .distinct().sorted(Comparator.reverseOrder()).skip(1).findFirst())
            .isEmpty();  // only 1 distinct value
    }

    @Test void negativeNumbers() {
        assertThat(List.of(-10, -20, -5, -1).stream()
            .distinct().sorted(Comparator.reverseOrder()).skip(1).findFirst())
            .contains(-5);  // -1 is largest, -5 is second
    }
}
